ALTER TABLE users MODIFY id CHAR(36) NOT NULL, MODIFY email VARCHAR(254) NOT NULL, MODIFY firstname VARCHAR(100) NOT NULL, MODIFY lastname VARCHAR(100) NOT NULL, ADD COLUMN active BOOLEAN NOT NULL DEFAULT TRUE, ADD COLUMN updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), ADD INDEX idx_users_created_at (created_at);
